        opts = TransportOpts(
            last_event_id,
            reconnect_token,
            list(protocols or []),
            5 if max_reconnect_attempts is None else max_reconnect_attempts,
            1000 if reconnect_delay_ms is None else reconnect_delay_ms,
        )
        dial = Dial(self, op, args, x.options.get("raw"))
